import math

def parse_amount(text):
    if not isinstance(text, str):
        raise ValueError("input must be a string")
    text = text.strip()
    if not text:
        raise ValueError("empty input")
    text = text.replace(',', '.')
    try:
        value = float(text)
    except ValueError:
        raise ValueError("non-finite value")
    if math.isfinite(value) and value >= 0:
        return value
    raise ValueError("non-finite value")
